export const EFFORT_LEVELS: Record<Effort, { maxIterations: number; hint: string }> = {
  low: {
    maxIterations: 6,
    hint: "Reasoning effort: minimal. Think only as much as strictly needed — a one-line plan at most, then act. Prefer the most direct path and skip optional verification.",
  },
  medium: {
    maxIterations: 14,
    hint: [
      "Reasoning effort: deliberate. Before each action, think step by step in your thinking channel:",
      "state what you know, what you still need, and why the next action is the right one.",
      "After each result, check it against what you expected before moving on. Verify changes that could break things.",
    ].join(" "),
  },
  high: {
    maxIterations: 28,
    hint: [
      "Reasoning effort: extended. For every step, reason explicitly in your thinking channel before acting:",
      "(1) restate the goal in your own words, (2) list at least two candidate approaches, (3) pick one and justify it,",
      "(4) predict what the action should produce. After each result, compare prediction vs reality —",
      "any mismatch means stop and re-derive, not push forward. Read relevant context before editing; verify your work by running it.",
    ].join(" "),
  },
  max: {
    maxIterations: 50,
    hint: [
      "Reasoning effort: maximal deliberation. Treat every task as a problem to decompose:",
      "(1) break it into subproblems and order them by dependency, (2) for each, generate multiple hypotheses or designs,",
      "(3) adversarially attack your own favorite — what input, edge case, or failure mode breaks it? — and only proceed once it survives,",
      "(4) predict each action's outcome before running it and reconcile every surprise before continuing,",
      "(5) after the work is done, run a self-review pass: re-read everything you produced hunting for errors, then verify end-to-end with real runs.",
      "Spend tokens on thinking freely — depth is the point at this level.",
    ].join(" "),
  },
  ultracode: {
    maxIterations: Number.POSITIVE_INFINITY,
    hint: [
      "Reasoning effort: unbounded — think harder here than at any other level. Everything from max applies (decompose, multiple hypotheses, adversarial self-attack, predict-then-reconcile, final self-review), plus full orchestration with no round limit:",
      "1. PLAN — investigate enough to understand the task, reason through the design space in your thinking channel, then state a short plan.",
      "2. TODOS — call todo_write with the plan as a checklist; keep statuses updated as you work (exactly one item in_progress at a time).",
      "3. DELEGATE — split independent work across subagents with spawn_agent (returns instantly).",
      "4. WORK WHILE THEY WORK — keep making progress yourself, then collect with await_agents.",
      "5. VERIFY — run builds/tests, fix failures, repeat until everything passes; distrust your own success claims until proven by a run.",
      "6. Only conclude when every todo is done, verified, and has survived your own attempt to refute it.",
    ].join("\n"),
  },
};
